NOTES = {
    'ONE_ISLAND': "One Island (FireRed map 3.12, 24 x 20): the Network Center on its terrace, the two houses, the steps down to the pier;\nthe harbour's door is the mat at the pier's end, its roof the row below. Kindle Road east along the sand, Treasure Beach\nsouth across the water (Surf).",
    'TREASURE_BEACH': "Treasure Beach (FireRed map 3.46, 24 x 40): the sea south of One Island with its rocks (each 2 x 2, all solid),\nthe beach, the tall grass in its middle, the cliffs. The swimmer and the boy stand where FireRed has them; the\nfisherman is our own.",
    'PALLET_TOWN': "Pallet Town (FireRed map 3.0, 24 x 20): your house top left, the rival's top right, Oak's Lab, the fenced flower garden,\nthe pond at the bottom: Route 21 south across it (Surf), Route 1 north through the gap in the trees.",
    'KANTO_ROUTE_1': "Route 1 (FireRed map 3.19, 24 x 40): Pallet south, Viridian north; every ledge a real one-way hop south, the tall grass,\nthe Mart clerk with the free Potion where FireRed stands him. FireRed's second person (a boy at 19,16) is left out.",
    'VIRIDIAN_CITY': "Viridian City (FireRed map 3.1, 48 x 40): the paved streets, the Gym top right with its porch, the house and the School,\nthe Mart, the Center; the pond (Surf), the ledges along the south, two small trees to Cut. Route 2 north, Route 22 west,\nRoute 1 south. The old man lies on the north road where FireRed has him.",
    'KANTO_ROUTE_22': "Route 22 (FireRed map 3.41, 48 x 24): in from Viridian on the east, the tall grass either side of the pond, the ledges,\nthe League's front gate top left (its doors lead on to Route 23). FireRed's rival stands at 25,4: left out.",
    'KANTO_ROUTE_2': "Route 2 (FireRed map 3.20, 24 x 80), whole: Viridian south, Pewter north; the west side is cut in two by the Forest,\nentered at its south gate and left by its north gate (their doors lead straight into the Forest: the gatehouses'\ninsides aren't built). The east side lies behind small trees (Cut): Diglett's Cave, the house, the east gatehouse\n(Oak's Aide: ours opens his option at either door; FireRed walks through it).",
    'VIRIDIAN_FOREST': "Viridian Forest (FireRed map 1.0, 54 x 69): in by the south gate, out by the north gate, both on Route 2; the tall grass\nlanes between the tree rows, the five Bug Catchers where FireRed stands its trainers (named in the order you meet them\nfrom the south), six signs.",
    'PEWTER_CITY': "Pewter City (FireRed map 3.2, 48 x 40): the Museum (hall, porch and east wing) along the top behind its ledge, the Gym\nwith its porch, the two houses, the Mart, the Center, the fenced flower garden; Route 2 south, Route 3 east.",
    'KANTO_ROUTE_3': "Route 3 (FireRed map 3.21, 84 x 20) with the foot of Mt. Moon above its east end (the west 22 columns of FireRed's\nRoute 4, 3.22, joined where the game joins them): Pewter west; the ledges; four of FireRed's eight trainer spots;\nthe Pokemon Center and Mt. Moon's mouth. 84 x 40 in all; the rest of the upper half is rock.",
    'MT_MOON': "Mt. Moon (FireRed maps 1.1, 1.2, 1.3: 1F 48 x 40, B1F 49 x 40, B2F 48 x 40): every ladder joined to the very ladder\nFireRed joins it to; B2F's ledges; the fossils and the Super Nerd, the Rockets and 1F's trainers on FireRed's spots.",
    'KANTO_ROUTE_4': "Route 4 east of Mt. Moon (FireRed map 3.22, its columns 22-107: 86 x 20): out of the mountain's far mouth, down\nthe ledges (east, west and south hops) to Cerulean City. Its west 22 columns are on our Route 3.",
    'CERULEAN_CITY': "Cerulean City (FireRed map 3.3, 48 x 40): Nugget Bridge north over the river, the fenced town, the Gym with its\nporch, the Center, the Mart between two houses, the Bike Shop, the houses with their back doors, the small tree\nto Cut by the south hedge; Cerulean Cave's mouth across the water in the west. The Center and Mart have their\nrooms; the other buildings' insides aren't built yet.",
    'KANTO_ROUTE_24': "Route 24 (FireRed map 3.43, 24 x 40): Nugget Bridge north out of Cerulean over the river (Surf beside it), the five\ntrainers on it and the Rocket at its head, the camper in the grass; the ledges at the top; Route 25 east.",
    'KANTO_ROUTE_25': "Route 25 (FireRed map 3.44, 72 x 20): east from Nugget Bridge's head through the trees and FireRed's nine trainers to\nBill's Sea Cottage on the cape, its two ponds and the fenced shore.",
    'BILLS_HOUSE': "Bill's Sea Cottage inside (FireRed map 30.0, 15 x 11): the two pods of the Cell Separator, the machines and boxes round the walls, Bill.",
    'KANTO_ROUTE_5': "Route 5 (FireRed map 3.23, 48 x 40): south from Cerulean down the ledges or the two fenced side paths; the Day Care,\nthe Underground Path's way in, Saffron's north gatehouse (its north doors lead straight on to Saffron).",
    'KANTO_ROUTE_6': "Route 6 (FireRed map 3.24, 24 x 40): Saffron's south gatehouse at the top, the Underground Path's way in, the pond,\nthe ledges and tall grass down to Vermilion; FireRed's six trainers.",
    'KANTO_ROUTE_7': "Route 7 (FireRed map 3.25, 24 x 20): Celadon west, Saffron's west gatehouse east, the Underground Path's way in,\nthe ledge down the tall grass. FireRed has no trainers here.",
    'KANTO_ROUTE_8': "Route 8 (FireRed map 3.26, 72 x 20): Saffron's east gatehouse west, Lavender east; the Underground Path's way in,\nthe fenced yard of tall grass behind its small trees (Cut), FireRed's trainers (the twins stand as one).",
    'KANTO_ROUTE_9': "Route 9 (FireRed map 3.27, 72 x 20): east from Cerulean past the small tree (Cut), up and down the rock shelves and\ntheir ledges to Route 10; FireRed's nine trainers.",
    'KANTO_ROUTE_10': "Route 10, north (FireRed map 3.28, its rows 0-49: 24 x 50): in from Route 9, the Pokemon Center and Rock Tunnel's\nnorth mouth behind the small trees (Cut); down the river (Surf) the Power Plant.",
    'KANTO_ROUTE_10_SOUTH': "Route 10, south (FireRed map 3.28, its rows 50-79: 24 x 30): out of Rock Tunnel's south mouth, down the ledges to\nLavender Town; FireRed's four trainers.",
    'KANTO_ROUTE_11': "Route 11 (FireRed map 3.29, 72 x 20): east from Vermilion through the tall grass and FireRed's ten trainers to the\ngatehouse (its west door leads straight on to Route 12); Diglett's Cave's mouth by the west end.",
    'VERMILLION_CITY': "Vermilion City (FireRed map 3.5, 48 x 40): the Center between two houses at the top, the Fan Club, the Mart, the Gym\nbehind its small tree (Cut), the cleared lot with its Machop, the harbour at the bottom (its doors are the mats at the\npier's head); the sea west and south (Surf). Route 6 north, Route 11 east.",
    'LAVENDER_TOWN': "Lavender Town (FireRed map 3.4, 24 x 20): the Pokemon Tower top right, the Center top left, Mr. Fuji's house in the\nmiddle, the Mart, the two joined houses; Route 10 north, Route 8 west, Route 12 south. FireRed's Lavender has no Radio\nTower (that is HeartGold's), so ours has none on the map.",
    'CELADON_CITY': "Celadon City (FireRed map 3.6, 60 x 40): the Dept. Store and the apartment blocks along the top, the Mansion with its\nback door, the Center; the pond, the diner, the Game Corner and the prize corner beside it; the Gym in the south-west\nbehind its flower beds and ledge, the row of houses and the hotel in the south-east. Route 16 west, Route 7 east.",
    'SAFFRON_CITY': "Saffron City (FireRed map 3.10, 66 x 55): Silph Co. in the middle, the Gym and the Fighting Dojo side by side in the\nnorth-east, Copycat's house in the north row, the Mart, the Center, the apartment blocks, the blue railings; the\nfour gatehouses (north Route 5, south Route 6, west Route 7, east Route 8). OURS: FireRed's Saffron has no Magnet\nTrain: HeartGold's station stands in the trees of the north-west corner (16-24, 3-7), a gap in the railing below its door.",
    'DIGGLETT_CAVE': "Diglett's Cave (FireRed maps 1.36, 1.37, 1.38): the small room at each end and the long tunnel between them\n(85 x 80), joined by FireRed's own ladders. FireRed has no trainers in it.",
    'ROCK_TUNNEL': "Rock Tunnel (FireRed maps 1.81, 1.82: 1F and B1F, 48 x 40 each): dark; in from Route 10 at the north mouth, out to\nits south stretch; the four ladders each joined to FireRed's own far end; FireRed's fifteen trainers.",
    'UNDERGROUND_PATH': "The Underground Path (FireRed maps 1.30-1.35): the four stair buildings (Routes 5, 6, 7, 8) and the two tunnels under Saffron, north-south (8 x 63) and east-west (80 x 7), joined by FireRed's own stairs. The Fossil Maniac is ours.",
    'POWER_PLANT': "The Power Plant (FireRed map 1.95, 49 x 40): its halls and generator rooms as FireRed walls them; Zapdos in the north-west room where FireRed has it.",
    'ROCKET_HIDEOUT': "The Rocket Hideout (FireRed maps 1.42-1.45, B1F to B4F): its halls as FireRed walls them, the spin-tile mazes with\ntheir stop tiles, the stairs joined as FireRed joins them, FireRed's eleven Grunts on their own spots, Giovanni and\nthe Silph Scope on B4F. OURS: the lift's doors on B1F and B2F lead straight to B4F's and back, with no Lift Key.",
    'KANTO_SS_ANNE': "The S.S. Anne (FireRed maps 1.5-1.11): 1F with the gangway and its cabin corridor, 2F, 3F, the deck, B1F, the kitchen and\nthe captain's office, every staircase joined as FireRed joins it. OURS: six of 1F's cabin doors are our six cabin\nbattles; the other cabins (2F's, B1F's, 1F's seventh) stay shut; the rival waits on 2F by the captain's stairs.",
    'KANTO_ROUTE_12': "Route 12 (FireRed map 3.30, 24 x 120): the Silence Bridge - the piers south from Lavender, through the lookout\ngatehouse (walked through: in by one door, out by the other), past the strip of land west to Route 11 where Snorlax\nsleeps on the pier, the fishing house, down to Route 13. FireRed's trainers on their own spots.",
    'KANTO_ROUTE_13': "Route 13 (FireRed map 3.31, 72 x 20): the pier in from Route 12, the fence maze west to Route 14 with its tall grass\nbehind the small tree (Cut); FireRed's trainers on their own spots.",
    'KANTO_ROUTE_14': "Route 14 (FireRed map 3.32, 24 x 60): south from Route 13's fences down the sand paths, the tall grass behind its\nsmall trees (Cut), west to Route 15; FireRed's trainers on their own spots.",
    'KANTO_ROUTE_15': "Route 15 (FireRed map 3.33, 72 x 20): west from Route 14 along the two sand paths either side of the ledge and the\ntall grass, through the gatehouse (walked through) to Fuchsia; FireRed's trainers on their own spots.",
    'FUCHSIA_CITY': "Fuchsia City (FireRed map 3.7, 48 x 40): the Safari Zone's gate at the top, the zoo's six pens (walled on three sides,\na fence and a sign across the front), the Mart, the Safari office, the east pond behind its fence; along the bottom\nthe Gym, two houses, the Center, the Warden's house and the fishing brother's (its back door out to the pond).\nRoute 18 west, Route 15 east, Route 19 south.",
    'KANTO_ROUTE_16': "Route 16 (FireRed map 3.34, 48 x 20): west from Celadon; the upper way behind the small tree (Cut) through the\ngatehouse's upper doors to the quiet house; the lower way past Snorlax, asleep on the road, through its lower doors\nto the head of the Cycling Road and FireRed's bikers. The gatehouse is walked through.",
    'KANTO_ROUTE_17': "Route 17, the Cycling Road (FireRed map 3.35, 24 x 160): the long slope south between its guard rails - two paved\nlanes, the grass and sand between them, the ponds let into the road (Surf), the tall grass by the top, FireRed's ten\nbikers. Its rows pull you downhill; the last row is level ground.",
    'KANTO_ROUTE_18': "Route 18 (FireRed map 3.36, 60 x 20): the foot of the Cycling Road, east along the shore through the gatehouse\n(walked through) to Fuchsia; the fenced tall grass below it with FireRed's three bird keepers.",
    'KINDLE_ROAD': "Kindle Road (FireRed map 3.45, 24 x 140): the sand east of One Island, the long swim north between the rocks, the\nEmber Spa's mouth in the cliff, the grass and cracked rocks, up to Mt. Ember's foot. FireRed's trainers on their spots.",
    'TWO_ISLAND': "Two Island (FireRed map 3.13, 48 x 20): the harbour off the west shore, the Center on its rise, the market stall\nunder its awning (our Shop: its keeper stands where FireRed has him), the Game Corner and the house beside it,\nthe steps north to Cape Brink.",
    'CAPE_BRINK': "Cape Brink (FireRed map 3.47, 24 x 40): up from Two Island past the pond and its waterfall (Waterfall), the grass\non the west bank, the move tutor's house at the top.",
    'THREE_ISLAND': "Three Island (FireRed map 3.14, 24 x 40) with Three Isle Port (3.49, 48 x 20) joined below it as the game joins them:\nthe houses, the Mart, the Center, the bikers in the road; Bond Bridge west; south down the steps to the pier yard,\nthe harbour at the pier's end, and the mouth of Three Isle Path (the area THREE_ISLE_PORT: the tunnel and the\ngrass pocket beyond it, which is seen from here but reached only through the tunnel).",
    'THREE_ISLE_PORT': "Three Isle Path (FireRed map 2.34, 30 x 7) and the pocket of tall grass it comes out in (3.49's east side, columns\n26-43): in from the pier yard on Three Island, through the tunnel, out among the Dunsparce.",
    'BOND_BRIDGE': "Bond Bridge (FireRed map 3.48, 96 x 20): west from Three Island through the fenced lanes and ledges, the small trees\n(Cut), over the plank bridge across the inlet, the beach, to Berry Forest's way in. FireRed's trainers on their spots.",
    'MT_EMBER': "Mt. Ember (FireRed maps 1.97 the mountain 57 x 54, 1.98-1.100 the Summit Path, 1.101 the summit, 1.103-1.108, 1.96 and\n1.102 the Ruby Path): up from Kindle Road, the grass ledges and FireRed's three trainers, the two cave mouths of the\nSummit Path, Moltres on the summit; the Rockets stand at the Ruby Path's door in the east face. Every mouth and\nladder joined to the very one FireRed joins it to; its cracked rocks and boulders where the game has them.",
    'BERRY_FOREST': "Berry Forest (FireRed map 1.109, 57 x 47): in from Bond Bridge at the south-east, the paths between the big trees, the\nponds (Surf), the small trees (Cut), the ledges; Lostelle waits in the north-west clearing where FireRed has her.",
    'FOUR_ISLAND': "Four Island (FireRed map 3.15, 48 x 40): the Day Care and its fenced garden, the Center by its pond, the Mart and the\nhouse joined to it, Lorelei's house in the east, the harbour off the south-west beach; Icefall Cave's mouth across the\nnorth-east pond (Surf).",
    'ICEFALL_CAVE': "Icefall Cave (FireRed maps 1.110-1.113): the entrance with its pool and waterfall (Waterfall), 1F with its thin\nice (step on it and you drop to the same spot on B1F), B1F's sheet ice, the back cave where Lorelei faces the\nRockets. Every ladder joined as FireRed joins it.",
    'FIVE_ISLAND': "Five Island (FireRed map 3.16, 24 x 20): the Center and the purple house on the rise, the east house, the beach round\nit, the harbour off the south pier. Five Isle Meadow east along the sand; Water Labyrinth north across the sea (Surf).",
    'FIVE_ISLE_MEADOW': "Five Isle Meadow (FireRed map 3.56, 24 x 40): east of Five Island, the tall grass among the trees, the Rocket Warehouse\nwith its locked door, the steps and ledges down to the south shore; Memorial Pillar east across the sea. FireRed's\nthree Rockets on their spots.",
    'ROCKET_WAREHOUSE': "The Rocket Warehouse (FireRed map 1.114, 29 x 27): its spin tiles and stop tiles as the game has them, the\nRockets and Scientist Gideon on FireRed's spots, the two Admins (the story's battle) where they stand.",
    'MEMORIAL_PILLAR': "Memorial Pillar (FireRed map 3.57, 24 x 60): across the sea from Five Isle Meadow, the long strip of tall grass south\nto the islet with the memorial stone. FireRed's three Bird Keepers on their spots.",
    'WATER_LABYRINTH': "Water Labyrinth (FireRed map 3.55, 72 x 20): the sea north of Five Island, a maze of rocks, with the islet where the\nold man keeps his Egg. Resort Gorgeous lies north. FireRed's one trainer on her spot.",
    'RESORT_GORGEOUS': "Resort Gorgeous (FireRed map 3.54, 72 x 20): the beach and Selphy's villa in its fenced garden, the islets, Lost Cave's\nmouth in the rock to the east; Water Labyrinth south. FireRed's seven trainers on their spots.",
    'SIX_ISLAND': "Six Island (FireRed map 3.18, 24 x 30): the Center and the Mart on the north road, the house below them, the ledges,\nthe steps down to the harbour; Water Path east.",
    'WATER_PATH': "Water Path (FireRed map 3.60, 24 x 100): the long shore east of Six Island: north past the two houses to Green Path,\nsouth down the beach and the steps to Ruin Valley, the sea alongside. FireRed's six trainers on their spots.",
    'GREEN_PATH': "Green Path (FireRed map 3.59, 72 x 20): west from Water Path along the fenced lane, Pattern Bush's two ways in among\nthe trees, then the sea west and north to Outcast Island. FireRed's one trainer on her spot.",
    'PATTERN_BUSH': "Pattern Bush (FireRed map 1.121, 60 x 32): the wood of tall grass grown in patterns, in from Green Path at its east\nend or its west. FireRed's twelve trainers on their spots.",
    'OUTCAST_ISLAND': "Outcast Island (FireRed map 3.58, 24 x 80): the sea north of Green Path up to the lonely island and Altering Cave's\nmouth. FireRed's five trainers on their spots.",
    'SEVII_ALTERING_CAVE': "Altering Cave (FireRed map 1.122, 32 x 24): one winding chamber on Outcast Island.",
    'RUIN_VALLEY': "Ruin Valley (FireRed map 3.61, 48 x 40): in from Water Path at the north-east, the grass terraces and ledges, the sand\npaths and steps down to the pool with the ruin in it: the Dotted Hole's door. The boulders (Strength) and FireRed's\nfive trainers where the game has them.",
    'DOTTED_HOLE': "The Dotted Hole (FireRed maps 1.115-1.120): on each floor four holes, one of them the way on (up, left, right, down, as\nthe braille says) and the others back to the start, joined exactly as FireRed joins them; the Sapphire at the bottom.",
    'SEVEN_ISLAND': "Seven Island (FireRed map 3.17, 24 x 20) with the Trainer Tower's grounds (3.62, 120 x 40) joined above it as the game\njoins them: the Center, the Mart, the house, the harbour; the road north past the beach to the Tower on its rock\n(our Trainer Tower challenge is its door); south to Canyon Entrance. The grounds' two trainers aren't placed\n(a town map has no trainer spots).",
    'CANYON_ENTRANCE': "Canyon Entrance (FireRed map 3.63, 24 x 40): south of Seven Island, the grass terraces and steps winding down and\neast into Sevault Canyon. FireRed's five trainers on their spots.",
    'SEVAULT_CANYON': "Sevault Canyon (FireRed map 3.64, 24 x 80): in from Canyon Entrance at the north-west, the sand shelves, steps and\ngrass down the canyon, the Tanoby Key's cave, the lone house, the last steps to the shore: Tanoby Ruins south. The\ncracked rocks and boulders and FireRed's six trainers where the game has them.",
    'TANOBY_RUINS': "Tanoby Ruins (FireRed map 3.65, 144 x 20) and its seven chambers (2.27-2.33, each 23 x 17): the sea south of Sevault\nCanyon with its seven islets, a ruin's door on each leading into its own chamber, where the Unown are.\nFireRed's four trainers on their spots.",
    'LOST_CAVE': "Lost Cave (FireRed maps 2.12-2.26): the entrance and ten rooms of four ways each, the right way on and the wrong\nways back to the first room exactly as FireRed joins them, the four side rooms; Selphy in the last room.\nFireRed's two trainers on their spots.",
    'NAVEL_ROCK': "Navel Rock (FireRed maps 2.0, 2.36, 2.54, 2.55, 2.39-2.53, 2.37, 2.38): the island, the cave in, the fork, the long\nstairs, the four flights up to Ho-Oh's summit and the eleven down to Lugia's base, joined as FireRed joins them.",
    'BIRTH_ISLAND': "Birth Island (FireRed map 2.56, 30 x 30): the bare triangular island and the triangle at its heart.",
    'KANTO_ROUTE_19': "Route 19 (FireRed map 3.37, 24 x 60): the beach below Fuchsia with its ledges, then the open sea south between the\nrocks (Surf), west on to Route 20; FireRed's swimmers on their own spots.",
    'KANTO_ROUTE_20': "Route 20 (FireRed map 3.38, 120 x 20): the sea from Route 19 west to Cinnabar, Seafoam's island in the middle with\nits two cave mouths, the sandbars; FireRed's swimmers on their own spots.",
    'KANTO_ROUTE_21': "Route 21 (FireRed maps 3.39 over 3.40, 24 x 100): the tall grass and the fishers' shore below Pallet, then the sea south\nbetween the rocks and sandbars to Cinnabar (Surf); FireRed's trainers on their own spots.",
    'CINNABAR_ISLAND': "Cinnabar Island (FireRed map 3.8, 24 x 20): the burnt-out Pokemon Mansion and the Gym along the top, the Pokemon Lab,\nthe Center and the Mart below, the sea all round (Surf). Route 21 north, Route 20 east. HEARTGOLD'S: the volcano's\nmouth in the east cliff.",
    'SEAFOAM_ISLANDS': "The Seafoam Islands (FireRed maps 1.83-1.87, 38 x 24 each): in at either mouth on Route 20, every ladder joined as FireRed joins it, the holes that drop you a floor, B3F's and B4F's currents (and B3F's waterfalls, which carry you down), Articuno at the top of B4F. OURS: boulders move by Strength and the slide puzzle; 1F's two land on B3F at once; B3F's two holes take boulders only, and the foot of its falls drops you into B4F's east channel.",
    'FARAWAY_ISLAND': "Faraway Island (Emerald's, from Jordan's two pictures, 34 x 46 and 29 x 26): the pier, the path up the cliffs by its\nfour flights of steps, the grove and its ponds, the way in to the forest clearing of long grass where Mew is.\nWhere you can stand is Emerald's own data; the way to the forest crosses two of the grove's ponds (Surf).",
    'KANTO_ROUTE_23': "Route 23 (FireRed map 3.42, 24 x 160): from the gatehouse on Route 22's side north through the eight badge gates and\ntheir guards, across the ponds (Surf), up the plateau to Victory Road's mouth; out of Victory Road's other mouth,\nthe forecourt of bollards up to Indigo Plateau.",
    'INDIGO_PLATEAU': "Indigo Plateau (FireRed map 3.9, 24 x 20): up the stairs from Route 23 into the yard, the Pokemon League across the\ntop (its lobby holds the nurse, the clerk and the door to the Elite Four). OURS: the booth for the ride to Johto.",
    'VICTORY_ROAD': "Victory Road (FireRed maps 1.39-1.41: 1F 48 x 22, 2F 51 x 22, 3F 45 x 22): in from Route 23 on 1F, up and down its ladders as FireRed joins them, out of 2F to Route 23's forecourt; its boulders (Strength), FireRed's trainers on their own spots. NOT BUILT: the floor switches and their barriers.",
    'SAFARI_ZONE': "The Safari Zone (FireRed maps 1.63-1.66): the Center, East, North and West areas, each tile for tile, side by side on one map (North above the Center, West and East either side); every gate is a passage joined to the gate FireRed joins it to; the Gold Teeth in the West. Its four rest houses and the Secret House are rooms (FireRed rooms 1.67-1.71), each a floor of this map: in by its door, out by its mat. OURS in the rooms: a table, a bed, a TV, a clock (and a fridge).",
    'POKEMON_MANSION': "The Pokemon Mansion (FireRed maps 1.59-1.62: 1F, 2F, 3F, B1F, 38 wide): its burnt halls as FireRed walls them, every staircase joined as FireRed joins it, the holes in 3F's floor, FireRed's trainers on their own spots. OURS: the switch gates stand open; Burglar Simon on 3F has the Secret Key.",
}
